animated-stepper.component:
'use client';

import type { CSSProperties } from 'react';
import './animated-stepper.css';

export interface StepperProps {
  steps: string[];
  /** Index of the current step, starting at 0. */
  current: number;
  /** Called when a step is chosen directly. */
  onStepChange: (index: number) => void;
  /** Accessible name for the list of steps. */
  label: string;
  className?: string;
}

/** Numbered steps joined by a line that fills as the user moves forward. */
export function Stepper({
  steps,
  current,
  onStepChange,
  label,
  className = '',
}: StepperProps) {
  const progress = steps.length > 1 ? current / (steps.length - 1) : 1;
  return (
    <ol
      className={`mg-stepper ${className}`}
      aria-label={label}
      style={
        {
          '--mg-count': steps.length,
          '--mg-progress': progress,
        } as CSSProperties
      }
    >
      {steps.map((step, index) => {
        const state =
          index < current ? 'done' : index === current ? 'current' : 'upcoming';
        return (
          <li key={step} className='mg-stepper__step' data-state={state}>
            <button
              type='button'
              className='mg-stepper__button'
              aria-current={state === 'current' ? 'step' : undefined}
              aria-label={`Step ${index + 1} of ${steps.length}: ${step}${
                state === 'done' ? ' (completed)' : ''
              }`}
              onClick={() => onStepChange(index)}
            >
              <span className='mg-stepper__dot' aria-hidden='true'>
                {state === 'done' ? '✓' : index + 1}
              </span>
              <span className='mg-stepper__name' aria-hidden='true'>
                {step}
              </span>
            </button>
          </li>
        );
      })}
    </ol>
  );
}

animated-stepper.css:
.mg-stepper {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--mg-count), minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The track runs between the centers of the first and last dots. */
.mg-stepper::before,
.mg-stepper::after {
  position: absolute;
  top: 21px;
  left: calc(50% / var(--mg-count));
  height: 3px;
  border-radius: 3px;
  content: '';
}

.mg-stepper::before {
  right: calc(50% / var(--mg-count));
  background: var(--mg-line, #d6def2);
}

.mg-stepper::after {
  width: calc((100% - 100% / var(--mg-count)) * var(--mg-progress));
  background: var(--mg-accent, #164cff);
  transition: width 450ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-stepper__button {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 6px;
  justify-items: center;
  width: 100%;
  padding: 4px 2px;
  border: 0;
  border-radius: 10px;
  background: none;
  color: #46527a;
  font: inherit;
  cursor: pointer;
}

.mg-stepper__button:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-stepper__dot {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 2px solid var(--mg-line, #d6def2);
  border-radius: 50%;
  background: #fff;
  font-weight: 700;
  transition:
    background-color 300ms ease 150ms,
    border-color 300ms ease 150ms,
    color 300ms ease 150ms,
    transform 300ms cubic-bezier(0.3, 1.5, 0.5, 1) 150ms;
}

.mg-stepper__step[data-state='done'] .mg-stepper__dot {
  border-color: var(--mg-accent, #164cff);
  background: var(--mg-accent, #164cff);
  color: #fff;
}

.mg-stepper__step[data-state='current'] .mg-stepper__dot {
  border-color: var(--mg-accent, #164cff);
  color: var(--mg-ink, #0c1738);
  transform: scale(1.12);
}

.mg-stepper__step[data-state='current'] .mg-stepper__name {
  color: var(--mg-ink, #0c1738);
  font-weight: 600;
}

.mg-stepper__name {
  font-size: 0.86em;
}

@media (prefers-reduced-motion: reduce) {
  .mg-stepper::after,
  .mg-stepper__dot {
    transition: none;
  }
}

animated-stepper.usage:
import { useState } from 'react';
import { Stepper } from './animated-stepper';

const STEPS = ['Route', 'Crew', 'Supplies', 'Depart'];

export default function Demo() {
  const [step, setStep] = useState(1);
  const button = (disabled: boolean) =>
    ({
      minHeight: 44,
      padding: '0 16px',
      border: '1px solid #b9c5e6',
      borderRadius: 8,
      background: '#fff',
      color: disabled ? '#6b7699' : '#0c1738',
      font: 'inherit',
      fontWeight: 600,
      cursor: disabled ? 'default' : 'pointer',
    }) as const;
  return (
    <div style={{ display: 'grid', gap: 16, width: 360, maxWidth: '100%' }}>
      <Stepper
        steps={STEPS}
        current={step}
        onStepChange={setStep}
        label='Trip setup'
      />
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <button
          type='button'
          style={button(step === 0)}
          disabled={step === 0}
          onClick={() => setStep((s) => s - 1)}
        >
          Back
        </button>
        <button
          type='button'
          style={button(step === STEPS.length - 1)}
          disabled={step === STEPS.length - 1}
          onClick={() => setStep((s) => s + 1)}
        >
          Next
        </button>
      </div>
    </div>
  );
}

animated-tabs.component:
'use client';

import {
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import './animated-tabs.css';

export interface AnimatedTab {
  id: string;
  label: string;
  content: ReactNode;
}

export interface AnimatedTabsProps {
  tabs: AnimatedTab[];
  /** Accessible name for the tab list. */
  label: string;
  className?: string;
}

/** Tabs with an indicator that slides to the active tab. */
export function AnimatedTabs({
  tabs,
  label,
  className = '',
}: AnimatedTabsProps) {
  const [active, setActive] = useState(tabs[0]?.id);
  const [bar, setBar] = useState({ left: 0, width: 0 });
  const list = useRef<HTMLDivElement>(null);
  const baseId = useId();

  useEffect(() => {
    const measure = () => {
      const tab = list.current?.querySelector<HTMLElement>(
        '[aria-selected="true"]'
      );
      if (tab) setBar({ left: tab.offsetLeft, width: tab.offsetWidth });
    };
    measure();
    if (typeof ResizeObserver === 'undefined' || !list.current) return;
    const observer = new ResizeObserver(measure);
    observer.observe(list.current);
    return () => observer.disconnect();
  }, [active, tabs]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const index = tabs.findIndex((tab) => tab.id === active);
    const next: Record<string, number> = {
      ArrowRight: (index + 1) % tabs.length,
      ArrowLeft: (index - 1 + tabs.length) % tabs.length,
      Home: 0,
      End: tabs.length - 1,
    };
    if (!(event.key in next)) return;
    event.preventDefault();
    const target = tabs[next[event.key]];
    setActive(target.id);
    list.current
      ?.querySelector<HTMLElement>(`[data-tab="${target.id}"]`)
      ?.focus();
  };

  return (
    <div className={`mg-tabs ${className}`}>
      <div
        ref={list}
        className='mg-tabs__list'
        role='tablist'
        aria-label={label}
        onKeyDown={onKeyDown}
      >
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type='button'
            role='tab'
            id={`${baseId}-tab-${tab.id}`}
            data-tab={tab.id}
            aria-selected={tab.id === active}
            aria-controls={`${baseId}-panel-${tab.id}`}
            tabIndex={tab.id === active ? 0 : -1}
            className='mg-tabs__tab'
            onClick={() => setActive(tab.id)}
          >
            {tab.label}
          </button>
        ))}
        <span
          className='mg-tabs__bar'
          aria-hidden='true'
          style={{ width: bar.width, transform: `translateX(${bar.left}px)` }}
        />
      </div>
      {tabs.map((tab) => (
        <div
          key={tab.id}
          role='tabpanel'
          id={`${baseId}-panel-${tab.id}`}
          aria-labelledby={`${baseId}-tab-${tab.id}`}
          hidden={tab.id !== active}
          tabIndex={0}
          className='mg-tabs__panel'
        >
          {tab.content}
        </div>
      ))}
    </div>
  );
}

