  return (
    <div style={{ display: 'grid', gap: 10, justifyItems: 'center' }}>
      <Dock items={items} label='Apps' />
      <span role='status' style={{ color: '#46527a' }}>
        Open: {chosen}
      </span>
    </div>
  );
}

expandable-card.component:
'use client';

import { useId, useState, type ReactNode } from 'react';
import './expandable-card.css';

export interface ExpandableCardProps {
  title: string;
  summary: string;
  children: ReactNode;
  defaultOpen?: boolean;
  className?: string;
}

/** A card that grows to reveal more detail, and shrinks back. */
export function ExpandableCard({
  title,
  summary,
  children,
  defaultOpen = false,
  className = '',
}: ExpandableCardProps) {
  const [open, setOpen] = useState(defaultOpen);
  const panelId = useId();
  return (
    <div className={`mg-expand ${className}`} data-open={open}>
      <button
        type='button'
        className='mg-expand__toggle'
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((value) => !value)}
      >
        <span>
          <strong className='mg-expand__title'>{title}</strong>
          <span className='mg-expand__summary'>{summary}</span>
        </span>
        <span className='mg-expand__chevron' aria-hidden='true' />
      </button>
      <div id={panelId} className='mg-expand__panel'>
        <div className='mg-expand__clip'>
          <div className='mg-expand__body'>{children}</div>
        </div>
      </div>
    </div>
  );
}

expandable-card.css:
.mg-expand {
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 14px;
  background: #fff;
  color: var(--mg-ink, #0c1738);
  transition: box-shadow 300ms ease;
}

.mg-expand[data-open='true'] {
  box-shadow: 0 16px 32px -18px rgba(12, 23, 56, 0.4);
}

.mg-expand__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  min-height: 48px;
  padding: 16px 18px;
  border: 0;
  border-radius: 14px;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.mg-expand__toggle:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-expand__title,
.mg-expand__summary {
  display: block;
}

.mg-expand__summary {
  margin-top: 2px;
  color: #46527a;
  font-size: 0.92em;
}

.mg-expand__chevron {
  flex: none;
  width: 10px;
  height: 10px;
  border-right: 2px solid var(--mg-accent, #164cff);
  border-bottom: 2px solid var(--mg-accent, #164cff);
  transform: translateY(-3px) rotate(45deg);
  transition: transform 300ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.mg-expand[data-open='true'] .mg-expand__chevron {
  transform: translateY(2px) rotate(225deg);
}

/* 0fr → 1fr animates to the content's natural height. */
.mg-expand__panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 340ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.mg-expand[data-open='true'] .mg-expand__panel {
  grid-template-rows: 1fr;
}

.mg-expand__clip {
  min-height: 0;
  overflow: hidden;
  visibility: hidden;
  transition: visibility 0s 340ms;
}

.mg-expand[data-open='true'] .mg-expand__clip {
  visibility: visible;
  transition-delay: 0s;
}

.mg-expand__body {
  padding: 0 18px 18px;
  color: #46527a;
}

@media (prefers-reduced-motion: reduce) {
  .mg-expand__panel,
  .mg-expand__chevron,
  .mg-expand__clip {
    transition: none;
  }
}

