'use client';

import { useEffect, useRef, useState } from 'react';
import './morphing-status-badge.css';

export type BadgeStatus = 'idle' | 'loading' | 'success' | 'error';

export interface StatusBadgeProps {
  status: BadgeStatus;
  /** Override the default wording for any status. */
  labels?: Partial<Record<BadgeStatus, string>>;
  className?: string;
}

const DEFAULT_LABELS: Record<BadgeStatus, string> = {
  idle: 'Ready',
  loading: 'Saving',
  success: 'Saved',
  error: 'Failed',
};

/** One badge that changes color, icon, label and width between statuses. */
export function StatusBadge({
  status,
  labels,
  className = '',
}: StatusBadgeProps) {
  const text = labels?.[status] ?? DEFAULT_LABELS[status];
  const label = useRef<HTMLSpanElement>(null);
  const [width, setWidth] = useState<number>();

  // Measure the new label so the badge can animate to its width.
  useEffect(() => {
    if (label.current) setWidth(label.current.offsetWidth);
  }, [text]);

  return (
    <span
      className={`mg-badge ${className}`}
      data-status={status}
      role='status'
    >
      <span className='mg-badge__icon' aria-hidden='true' />
      <span className='mg-badge__clip' style={{ width }}>
        <span key={status} ref={label} className='mg-badge__label'>
          {text}
        </span>
      </span>
    </span>
  );
}

morphing-status-badge.css:
.mg-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 0 14px 0 10px;
  border-radius: 999px;
  background: #e6ecff;
  color: #0c1738;
  font-weight: 600;
  transition:
    background-color 300ms ease,
    color 300ms ease;
}

.mg-badge[data-status='loading'] {
  background: #164cff;
  color: #fff;
}

.mg-badge[data-status='success'] {
  background: #b6ff3b;
  color: #0c1738;
}

.mg-badge[data-status='error'] {
  background: #b3122c;
  color: #fff;
}

.mg-badge__clip {
  display: inline-block;
  overflow: hidden;
  white-space: nowrap;
  transition: width 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-badge__label {
  display: inline-block;
  animation: mg-badge-in 300ms ease both;
}

/* One element draws every icon: dot, spinner, check and cross. */
.mg-badge__icon {
  position: relative;
  flex: none;
  width: 14px;
  height: 14px;
}

.mg-badge__icon::before,
.mg-badge__icon::after {
  position: absolute;
  box-sizing: border-box;
  content: '';
  transition: all 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-badge[data-status='idle'] .mg-badge__icon::before {
  inset: 3px;
  border-radius: 50%;
  background: currentColor;
}

.mg-badge[data-status='loading'] .mg-badge__icon::before {
  inset: 0;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #fff;
  border-radius: 50%;
  animation: mg-badge-spin 800ms linear infinite;
}

.mg-badge[data-status='success'] .mg-badge__icon::before {
  top: 1px;
  left: 4px;
  width: 6px;
  height: 10px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
}

.mg-badge[data-status='error'] .mg-badge__icon::before,
.mg-badge[data-status='error'] .mg-badge__icon::after {
  top: 6px;
  left: 0;
  width: 14px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transform: rotate(45deg);
}

.mg-badge[data-status='error'] .mg-badge__icon::after {
  transform: rotate(-45deg);
}

@keyframes mg-badge-in {
  from {
    opacity: 0;
    transform: translateY(60%);
  }
}

@keyframes mg-badge-spin {
  to {
    transform: rotate(1turn);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-badge,
  .mg-badge__clip,
  .mg-badge__icon::before,
  .mg-badge__icon::after {
    transition: none;
  }
  .mg-badge__label {
    animation: none;
  }
  /* Keep a slow spin so "loading" still reads as in progress. */
  .mg-badge[data-status='loading'] .mg-badge__icon::before {
    animation-duration: 2.4s;
  }
}

morphing-status-badge.usage:
import { useEffect, useState } from 'react';
import { StatusBadge, type BadgeStatus } from './morphing-status-badge';

const button = {
  minHeight: 44,
  padding: '0 14px',
  border: '1px solid #b9c5e6',
  borderRadius: 8,
  background: '#fff',
  color: '#0c1738',
  font: 'inherit',
  fontWeight: 600,
  cursor: 'pointer',
} as const;

export default function Demo() {
  const [status, setStatus] = useState<BadgeStatus>('idle');
  const [outcome, setOutcome] = useState<BadgeStatus>('success');

  // After "loading", settle on the chosen outcome.
  useEffect(() => {
    if (status !== 'loading') return;
    const timer = window.setTimeout(() => setStatus(outcome), 1400);
    return () => window.clearTimeout(timer);
  }, [status, outcome]);

  const run = (result: BadgeStatus) => {
    setOutcome(result);
    setStatus('loading');
  };

  return (
    <div style={{ display: 'grid', gap: 16, justifyItems: 'center' }}>
      <StatusBadge status={status} />
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 8,
          justifyContent: 'center',
        }}
      >
        <button type='button' style={button} onClick={() => run('success')}>
          Save
        </button>
        <button type='button' style={button} onClick={() => run('error')}>
          Save and fail
        </button>
        <button type='button' style={button} onClick={() => setStatus('idle')}>
          Reset
        </button>
      </div>
    </div>
  );
}

